type SocialDockProps = {
  orientation: 'horizontal' | 'vertical';
  className?: string;
  baseItemSize?: number;
  magnification?: number;
};

const SocialDock: React.FC<SocialDockProps> = ({
  orientation,
  className = '',
  baseItemSize: baseItemSizeProp,
  magnification: magnificationProp,
}) => {
  const measureRef = useRef<HTMLDivElement>(null);
  const [measuredBase, setMeasuredBase] = useState(72);

  useEffect(() => {
    if (orientation !== 'vertical') return;
    const el = measureRef.current;
    if (!el) return;

    const update = () => {
      const height = el.getBoundingClientRect().height;
      // A little under 1/4 so magnified items still fit with spacing.
      setMeasuredBase(Math.max(48, Math.floor(height * 0.22)));
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, [orientation]);

  const baseItemSize =
    baseItemSizeProp ?? (orientation === 'vertical' ? measuredBase : 58);
  const magnification =
    magnificationProp ??
    (orientation === 'vertical'
      ? Math.round(baseItemSize * 1.22)
      : 78);

  const items = useMemo<DockItemData[]>(
    () =>
      socialLinks.map((link) => ({
        label: link.label,
        onClick: () => {
          if (link.icon === 'email') {
            window.location.href = link.href;
            return;
          }
          window.open(link.href, '_blank', 'noopener,noreferrer');
        },
        icon: (
          <svg
            viewBox="0 0 24 24"
            fill={link.icon === 'email' ? 'none' : 'currentColor'}
            aria-hidden="true"
          >
            {paths[link.icon]}
          </svg>
        ),
      })),
    []
  );

  return (
    <div
      ref={measureRef}
      className={`social-dock social-dock--${orientation} ${className}`.trim()}
    >
      <Dock
        items={items}
        orientation={orientation}
        baseItemSize={baseItemSize}
        magnification={magnification}
        distance={orientation === 'vertical' ? Math.round(baseItemSize * 1.6) : 160}
      />
    </div>
  );
};

export default SocialDock;
